def minimize_string_value(s: str) -> str:
    freq = [0] * 26
    res = []

    for ch in s:
        if ch == '?':
            # find letter with minimal frequency, tie-break by smallest character
            min_freq = min(freq)
            for i in range(26):
                if freq[i] == min_freq:
                    chosen = chr(ord('a') + i)
