def prime_pairs(n):
    # Edge case: if n < 2, no primes exist
    if n < 2:
        return []

    # Sieve of Eratosthenes to mark primes up to n
    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False
    for i in range(2, int(n ** 0.5) + 1):
        if is_prime[i]:
            step = i
            start = i * i
            is_prime[start:n+1:step] = [False] * (((n - start) // step) + 1)

    # Collect prime pairs (x, y) with x <= y and x + y == n
    pairs = []
    limit = n // 2          # because x <= y implies x <= n/2
    for x in range(2, limit + 1):
        if is_prime[x]:
            y = n - x
            if y >= x and is_prime[y]:
                pairs.append([x, y])

    return pairs
