        dist[i][i] = 0

    # Add direct edges, keeping the minimum cost for each pair
    for u_str, v_str, w in zip(original, changed, cost):
        u = ord(u_str) - ord('a')
        v = ord(v_str) - ord('a')
        if w < dist[u][v]:
            dist[u][v] = w

    # Floyd‑Warshall to compute all‑pairs shortest paths
    for k in range(N):
        for i in range(N):
            if dist[i][k] == INF:
                continue
            for j in range(N):
                if dist[k][j] == INF:
                    continue
                nd = dist[i][k] + dist[k][j]
                if nd < dist[i][j]:
                    dist[i][j] = nd

    # Compute total cost to transform source into target
    total = 0
    for s_char, t_char in zip(source, target):
