    # We'll try to fill the grid using backtracking
    # We'll keep track of which cells are occupied
    grid = [[False]*W for _ in range(H)]

    def can_place(r, c, h, w):
        """Check if a h x w tile can be placed with top-left at (r,c)"""
        if r + h > H or c + w > W:
            return False
        for i in range(r, r+h):
            for j in range(c, c+w):
                if grid[i][j]:
                    return False
        return True

    def place(r, c, h, w, val):
        """Place or remove a h x w tile at (r,c)"""
        for i in range(r, r+h):
            for j in range(c, c+w):
                grid[i][j] = val

    def next_cell(r, c):
        """Get next empty cell to try filling"""
        for i in range(r, H):
            for j in range(c if i == r else 0, W):
                if not grid[i][j]:
                    return (i, j)
        return None

    used = [False]*N

    def backtrack():
        cell = next_cell(0, 0)
        if cell is None:
            return True
        r, c = cell

        for idx, (a, b) in enumerate(tiles):
            if used[idx]:
                continue
            # Try both orientations
            for h, w in [(a, b), (b, a)]:
                if can_place(r, c, h, w):
                    used[idx] = True
                    place(r, c, h, w, True)
                    if backtrack():
                        return True
                    place(r, c, h, w, False)
                    used[idx] = False
        return False

