from functools import lru_cache
from typing import List

def can_split_array(nums: List[int], m: int) -> bool:
    n = len(nums)

    # Prefix sums for O(1) subarray sum queries
    prefix = [0] * (n + 1)
    for i in range(n):
        prefix[i + 1] = prefix[i] + nums[i]

    def subarray_sum(l: int, r: int) -> int:
        return prefix[r + 1] - prefix[l]

    @lru_cache(None)
    def can_split(l: int, r: int) -> bool:
        length = r - l + 1
        if length == 1:
            return True
        # Try all possible split points
        for split in range(l, r):
            left_sum = subarray_sum(l, split)
            right_sum = subarray_sum(split + 1, r)
            left_len = split - l + 1
            right_len = r - split

            left_valid = (left_len == 1) or (left_sum >= m)
            right_valid = (right_len == 1) or (right_sum >= m)

            if left_valid and right_valid:
                if can_split(l, split) and can_split(split + 1, r):
                    return True
        return False

    return can_split(0, n - 1)
