def canTraverseAllPairs(nums):
    n = len(nums)
    if n == 1:
        return True

    max_val = max(nums)

    # Sieve for smallest prime factor (SPF)
    spf = list(range(max_val + 1))
    for i in range(2, int(max_val ** 0.5) + 1):
        if spf[i] == i:  # i is prime
            for j in range(i * i, max_val + 1, i):
                if spf[j] == j:
                    spf[j] = i

    # Disjoint Set Union (DSU)
    parent = list(range(n))
    rank = [0] * n

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1

    prime_to_index = {}  # first index that contains a given prime factor

    for i, num in enumerate(nums):
        if num == 1:
            # 1 cannot be connected to any other number
            return False
        # factorize num using spf
        x = num
        while x > 1:
            p = spf[x]
            while x % p == 0:
                x //= p
            if p in prime_to_index:
                union(i, prime_to_index[p])
            else:
                prime_to_index[p] = i

    # Check that all indices belong to the same connected component
    root = find(0)
    for i in range(1, n):
        if find(i) != root:
            return False
    return True
