def minimize_length(s: str) -> int:
    # Convert string to list for easier manipulation
    chars = list(s)
    changed = True

    while changed:
        changed = False
        i = 0
        while i < len(chars):
            c = chars[i]
            # Find closest occurrence to the left
            left = -1
            for j in range(i - 1, -1, -1):
                if chars[j] == c:
                    left = j
                    break
            # Find closest occurrence to the right
            right = -1
            for j in range(i + 1, len(chars)):
                if chars[j] == c:
                    right = j
                    break

            # If both left and right exist, delete them
            if left != -1 and right != -1:
                # Remove right first to keep indices correct
                del chars[right]
                del chars[left]
                # Since we removed two characters, i shifts
                if i > left:
                    i -= 1
                if i >= right:
                    i -= 1
                changed = True
            # If only right exists, delete it
            elif right != -1:
                del chars[right]
                changed = True
            # If only left exists, delete it
            elif left != -1:
                del chars[left]
                if i > left:
                    i -= 1
                changed = True
            else:
